"""Offline deterministic assembler; never submits or runs the Kaggle notebook."""
from __future__ import annotations

import base64
import hashlib
import json
import shutil
import zipfile
from pathlib import Path
from typing import Any

BUNDLE = Path(__file__).resolve().parent
ROOT = BUNDLE.parents[4]
PAYLOAD = BUNDLE / "payload"
PAYLOAD_ZIP = BUNDLE / "heat-torch-payload.zip"
NOTEBOOK = BUNDLE / "heat-tier2-t4x2.ipynb"
METADATA = BUNDLE / "kernel-metadata.json"
PACKAGE = BUNDLE / "heat-tier2-review-package.zip"
PACKAGE_SHA = BUNDLE / "heat-tier2-review-package.zip.sha256"


def digest(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            h.update(block)
    return h.hexdigest()


def write_json(path: Path, value: Any) -> None:
    path.write_text(json.dumps(value, indent=2, sort_keys=True, ensure_ascii=False) + "\n", encoding="utf-8")


def zip_files(path: Path, files: list[tuple[str, Path]]) -> None:
    with zipfile.ZipFile(path, "w", zipfile.ZIP_DEFLATED, compresslevel=9) as archive:
        for name, source in sorted(files):
            info = zipfile.ZipInfo(name, (1980, 1, 1, 0, 0, 0))
            info.compress_type = zipfile.ZIP_DEFLATED
            info.create_system = 3
            info.external_attr = 0o100644 << 16
            archive.writestr(info, source.read_bytes())


def make_payload() -> None:
    PAYLOAD.mkdir(parents=True, exist_ok=True)
    for entry in PAYLOAD.iterdir():
        if entry.is_file():
            entry.unlink()
    sources = {
        "heat_comparison_runner.py": BUNDLE / "heat_comparison_runner.py",
        "heat_common_eval.py": BUNDLE / "heat_common_eval.py",
        "heat_final_eval.py": BUNDLE / "heat_final_eval.py",
        "af_sciml_model.py": ROOT / "src/research_pipeline/sciml/model.py",
    }
    missing = [str(path) for path in sources.values() if not path.is_file()]
    if missing:
        raise FileNotFoundError("Missing static inputs: " + ", ".join(missing))
    for name, source in sources.items():
        shutil.copyfile(source, PAYLOAD / name)
    manifest = {
        "status": "DRAFT_UNVERIFIED",
        "runtime_dependencies": "Kaggle-preinstalled Torch and NumPy only; no pip or network",
        "model_snapshot": "af_sciml_model.py copied verbatim from src/research_pipeline/sciml/model.py",
        "files": {p.name: digest(p) for p in sorted(PAYLOAD.iterdir()) if p.is_file()},
        "arms": ["H-RBF", "H-BS", "H-FNN (Torch port of tutorial architecture/recipe)"],
        "cohort": {"smoke": [900], "paired_tier2": [901, 902, 903, 904, 905]},
        "pool": "Torch scrambled SobolEngine; interior 4096, IC 1024, boundaries 512 each; same NPZ across arms per seed",
        "training": "float64, hard exact traces, full-batch MSE((u_t-0.1*u_xx)/1.1); shared Adam-only recipe at 500 GPU-s/arm-seed, 120 GPU-s/arm smoke",
        "evaluation": "development 257x129 CUDA score per Tier2 run; after all training, separate CUDA-only confirmation pass on generated 512x256 grid",
        "budget": {"session_quota_cap_hours": 2, "aggregate_device_seconds_cap": 14400, "accelerator": "NvidiaTeslaT4 (T4x2)"},
    }
    write_json(PAYLOAD / "payload-manifest.json", manifest)
    zip_files(PAYLOAD_ZIP, [(p.name, p) for p in PAYLOAD.iterdir() if p.is_file()])


