def make_notebook() -> None:
    payload = base64.b64encode(PAYLOAD_ZIP.read_bytes()).decode("ascii")
    source = NOTEBOOK_TEMPLATE.replace("@@PAYLOAD_BASE64@@", payload)
    namespace: dict[str, Any] = {}
    exec(compile(source, "<offline-notebook-builder>", "exec"), namespace)
    notebook = namespace["nb"]
    for cell in notebook["cells"]:
        cell_source = "".join(cell.get("source", []))
