def checksums() -> None:
    excluded = {"SHA256SUMS.txt", PACKAGE.name, PACKAGE_SHA.name}
    lines = [f"{digest(p)}  {p.relative_to(BUNDLE).as_posix()}" for p in sorted(BUNDLE.rglob("*")) if p.is_file() and p.name not in excluded]
    (BUNDLE / "SHA256SUMS.txt").write_text("\n".join(lines) + "\n", encoding="utf-8")


def package() -> None:
    excluded = {PACKAGE.name, PACKAGE_SHA.name}
    members = [(p.relative_to(BUNDLE).as_posix(), p) for p in BUNDLE.rglob("*") if p.is_file() and p.name not in excluded]
    zip_files(PACKAGE, members)
    PACKAGE_SHA.write_text(f"{digest(PACKAGE)}  {PACKAGE.name}\n", encoding="utf-8")
    print(json.dumps({"package": str(PACKAGE), "sha256": digest(PACKAGE), "notebook": str(NOTEBOOK)}, indent=2))


def main() -> None:
    make_payload()
    make_notebook()
    make_metadata()
    checksums()
    package()


if __name__ == "__main__":
    main()
